INSERT INTO ubicacion (id_municipio, id_area_geografica, ciudad, zona, direccion_referencia) SELECT m.id_municipio, NULL, NULL, 'Ignorada', NULL FROM departamento d JOIN municipio m ON m.id_departamento = d.id_departamento WHERE UPPER(TRIM(d.nombre)) = UPPER('Santa Rosa')   AND UPPER(TRIM(m.nombre)) = UPPER('Barberena')   AND NOT EXISTS (SELECT 1 FROM ubicacion u WHERE u.id_municipio = m.id_municipio AND COALESCE(u.zona, '') = 'Ignorada');
